std::mutex data_mutex;
int shared_resource = 0;

void safe_access() {
    // RAII lock ensures unlock upon scope exit
    std::lock_guard<std::mutex> lock(data_mutex);
    shared_resource++; // Critical section
}

// Manual locking (less safe)
void manual_access() {
    data_mutex.lock();
    // Do work
    data_mutex.unlock();
}

std::atomic<long> transaction_id = 0;

void lock_free_increment() {
    // Atomically fetch old value and add 1
    long new_id = transaction_id.fetch_add(1);
}

// Simple atomic variable assignment
void direct_atomic_op() {
    transaction_id = 500;
}

std::mutex mtx;
std::condition_variable cv;
std::queue<int> data_queue;

void consumer_wait() {
    std::unique_lock<std::mutex> lock(mtx);
    // Wait until queue is not empty (spurious wakeups handled)
    cv.wait(lock, []{ return !data_queue.empty(); });
    int data = data_queue.front();
}

void producer_notify(int item) {
    {
        std::lock_guard<std::mutex> lock(mtx);
        data_queue.push(item);
    } // Lock released
    cv.notify_one();
}

// C-style thread synchronization using POSIX
pthread_mutex_t p_mtx = PTHREAD_MUTEX_INITIALIZER;
int p_resource = 0;

void posix_lock() {
    pthread_mutex_lock(&p_mtx);
    p_resource++;
    pthread_mutex_unlock(&p_mtx);
}
